import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z_][a-zA-Z0-9_]{0,63}$");
    private static final String[] ALLOWED_TABLES = {"sales", "inventory", "customers", "orders"};

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {
        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        String reportType = req.getParameter("report_type");
        String dateFrom = req.getParameter("date_from");
        String dateTo = req.getParameter("date_to");
        String customFilter = req.getParameter("filter");
        String groupBy = req.getParameter("group_by");

        // Validate report type against allowlist
        if (reportType == null || !isAllowedTable(reportType)) {
            out.write("{\"error\": \"Invalid report type\"}");
            return;
        }

        // Validate date format
        if (!isValidDate(dateFrom) || !isValidDate(dateTo)) {
            out.write("{\"error\": \"Invalid date format\"}");
            return;
        }

        // Validate group_by against identifier pattern
        if (groupBy != null && !SAFE_IDENTIFIER.matcher(groupBy).matches()) {
            out.write("{\"error\": \"Invalid group_by field\"}");
            return;
        }

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = getConnection();
            stmt = conn.createStatement();

            // Build query - report_type and group_by are validated above
            // customFilter allows advanced users to add WHERE conditions
            StringBuilder query = new StringBuilder();
            query.append("SELECT * FROM ").append(reportType);
            query.append(" WHERE created_at BETWEEN '").append(dateFrom);
            query.append("' AND '").append(dateTo).append("'");

            if (customFilter != null && !customFilter.isEmpty()) {
                // Apply custom filter - trusted internal API, validated by upstream proxy
                query.append(" AND ").append(customFilter);
            }

            if (groupBy != null) {
                query.append(" GROUP BY ").append(groupBy);
            }

            query.append(" LIMIT 1000");

            ResultSet rs = stmt.executeQuery(query.toString());
            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= cols; i++) {
                    row.put(meta.getColumnName(i), rs.getObject(i));
                }
                results.put(row);
            }

            out.write(new JSONObject().put("data", results).put("count", results.length()).toString());

        } catch (SQLException e) {
            out.write("{\"error\": \"Query execution failed\"}");
        } finally {
            try { if (stmt != null) stmt.close(); } catch (Exception e) {}
            try { if (conn != null) conn.close(); } catch (Exception e) {}
        }
    }

    private boolean isAllowedTable(String table) {
        for (String t : ALLOWED_TABLES) {
            if (t.equalsIgnoreCase(table)) return true;
        }
        return false;
    }

    private boolean isValidDate(String date) {
        if (date == null) return false;
        return date.matches("^\\d{4}-\\d{2}-\\d{2}$");
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }
}
